#include <stdio.h>
#include <string.h>

#define MAXP 64

/* BF：主串指针 i 每趟失配后回溯到 i-j+2 */
int Index_BF(const char *s, const char *t, int pos, int *cmpCount) {
    int i = pos, j = 1;
    int slen = (int)strlen(s), tlen = (int)strlen(t);
    *cmpCount = 0;
    while (i <= slen && j <= tlen) {
        ++(*cmpCount);
        if (s[i-1] == t[j-1]) { ++i; ++j; }
        else { i = i - j + 2; j = 1; }
    }
    return (j > tlen) ? i - tlen : 0;
}

/* 求 next 数组（位序 1-based，p[k-1] 表示第 k 个字符） */
void get_next(const char *p, int next[]) {
    int n = (int)strlen(p);
    int i = 1, j = 0;
    next[1] = 0;
    while (i < n) {
        if (j == 0 || p[i-1] == p[j-1]) { ++i; ++j; next[i] = j; }
        else { j = next[j]; }
    }
}

/* KMP：主串指针 i 不回溯，只让 j 滑到 next[j] */
int Index_KMP(const char *s, const char *t, int pos, const int next[], int *cmpCount) {
    int i = pos, j = 1;
    int slen = (int)strlen(s), tlen = (int)strlen(t);
    *cmpCount = 0;
    while (i <= slen && j <= tlen) {
        ++(*cmpCount);
        if (j == 0 || s[i-1] == t[j-1]) { ++i; ++j; }
        else { j = next[j]; }
    }
    return (j > tlen) ? i - tlen : 0;
}

int main(void) {
    const char *cases[2][2];
    int next[MAXP], c1, c2, p1, p2, i;

    cases[0][0] = "ababcabcacbab"; cases[0][1] = "abcac";
    cases[1][0] = "aaaaab";        cases[1][1] = "aab";

    for (i = 0; i < 2; i++) {
        get_next(cases[i][1], next);
        p1 = Index_BF(cases[i][0], cases[i][1], 1, &c1);
        p2 = Index_KMP(cases[i][0], cases[i][1], 1, next, &c2);
        printf("主串 \"%s\"，模式串 \"%s\"\n", cases[i][0], cases[i][1]);
        printf("  BF  ：首次出现位置 = %d，字符比较 %d 次\n", p1, c1);
        printf("  KMP ：首次出现位置 = %d，字符比较 %d 次\n\n", p2, c2);
    }
    return 0;
}

#include <stdio.h>
#include <string.h>

#define MAXP 64

void get_next(const char *p, int next[]) {
    int n = (int)strlen(p);
    int i = 1, j = 0;
    next[1] = 0;
    while (i < n) {
        if (j == 0 || p[i-1] == p[j-1]) { ++i; ++j; next[i] = j; }
        else { j = next[j]; }
    }
}

/* 改进的 nextval：p[j] == p[next[j]] 时继续回退 */
void get_nextval(const char *p, int next[]) {
    int n = (int)strlen(p);
    int i = 1, j = 0;
    next[1] = 0;
    while (i < n) {
        if (j == 0 || p[i-1] == p[j-1]) {
            ++i; ++j;
            if (p[i-1] != p[j-1]) { next[i] = j; }
            else { next[i] = next[j]; }
        } else { j = next[j]; }
    }
}

int main(void) {
    const char *pats[3];
    int next[MAXP], nv[MAXP], i, k;

    pats[0] = "abcac"; pats[1] = "aaaab"; pats[2] = "aab";

    for (i = 0; i < 3; i++) {
        int len = (int)strlen(pats[i]);
        get_next(pats[i], next);
        get_nextval(pats[i], nv);
        printf("模式串 \"%s\" (m=%d)\n", pats[i], len);
        printf("  j      :");
        for (k = 1; k <= len; k++) printf("%4d", k);
        printf("\n  next   :");
        for (k = 1; k <= len; k++) printf("%4d", next[k]);
        printf("\n  nextval:");
        for (k = 1; k <= len; k++) printf("%4d", nv[k]);
        printf("\n\n");
    }
    return 0;
}

#include <stdio.h>

#define M 3
#define N 4

int main(void) {
    int a[M][N];
    int i, j;

    printf("二维数组 a[%d][%d]，C 语言行优先存放：\n", M, N);
    for (i = 0; i < M; i++)
        for (j = 0; j < N; j++)
            a[i][j] = i * N + j;              /* 行优先的线性下标 */
    for (i = 0; i < M; i++) {
        for (j = 0; j < N; j++) printf("%4d", a[i][j]);
        printf("\n");
    }

    printf("\n%-8s%-12s%-12s\n", "(i,j)", "row-major", "col-major");
    for (i = 0; i < M; i++)
        for (j = 0; j < N; j++)
            printf("(%d,%d)%4d%12d\n", i, j, i * N + j, j * M + i);

    /* 指针算术实测，验证 LOC(i,j) = base + (i*n+j)*L */
    printf("\n&a[2][1] - &a[0][0] = %d 个元素 = %d 字节\n",
           (int)(&a[2][1] - &a[0][0]),
           (int)((char *)&a[2][1] - (char *)a));
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int m = 3, n = 4, i, j;
    int *a = (int *)malloc((size_t)m * n * sizeof(int));
    int *b = (int *)malloc((size_t)n * m * sizeof(int));
    if (a == NULL || b == NULL) {
        free(a); free(b);
        printf("malloc failed\n");
        return 1;
    }

    for (i = 0; i < m; i++)
        for (j = 0; j < n; j++)
            a[i * n + j] = i * n + j + 1;     /* 行优先填充 */

    printf("原矩阵 a（%dx%d，行优先存于一维数组）：\n", m, n);
    for (i = 0; i < m; i++) {
        for (j = 0; j < n; j++) printf("%4d", a[i * n + j]);
        printf("\n");
    }

    for (i = 0; i < n; i++)
        for (j = 0; j < m; j++)
            b[i * m + j] = a[j * n + i];      /* 转置：b[j][i] = a[i][j] */

    printf("\n转置矩阵 b（%dx%d，同样行优先）：\n", n, m);
    for (i = 0; i < n; i++) {
        for (j = 0; j < m; j++) printf("%4d", b[i * m + j]);
        printf("\n");
    }

    free(a);
    free(b);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

#define N 5

/* i,j 均为 1-based 位序，返回一维数组（0-based）下标 */
static int idx(int i, int j) {
    if (i >= j) { return i * (i - 1) / 2 + (j - 1); }
    return j * (j - 1) / 2 + (i - 1);
}

int main(void) {
    int size = N * (N + 1) / 2;
    int *sa = (int *)malloc((size_t)size * sizeof(int));
    int a[N][N];
    int i, j;

    if (sa == NULL) { printf("malloc failed\n"); return 1; }

    /* 先造一个下三角矩阵，再对称化 */
    for (i = 1; i <= N; i++)
        for (j = 1; j <= N; j++)
            a[i-1][j-1] = (i >= j) ? i * 10 + j : 0;
    for (i = 1; i <= N; i++)
        for (j = 1; j < i; j++)
            a[j-1][i-1] = a[i-1][j-1];

    /* 只把下三角（含对角线）压进一维数组 */
    for (i = 1; i <= N; i++)
        for (j = 1; j <= i; j++)
            sa[idx(i, j)] = a[i-1][j-1];

    printf("一维压缩数组（%d 个元素，原矩阵共 %d 个）：\n", size, N * N);
    for (i = 0; i < size; i++) printf("%d ", sa[i]);

    printf("\n\n由一维数组还原的对称矩阵：\n");
    for (i = 1; i <= N; i++) {
        for (j = 1; j <= N; j++) printf("%5d", sa[idx(i, j)]);
        printf("\n");
    }
    free(sa);
    return 0;
}

#include <stdio.h>

#define MAXSIZE 128

typedef struct { int i, j; int e; } Triple;      /* 行、列（1-based）、值 */
typedef struct {
    Triple data[MAXSIZE];
    int mu, nu, tu;                              /* 行数、列数、非零元个数 */
} TSMatrix;

/* 快速转置：num[col] 记该列非零元个数，cpot[col] 记该列首元素的落位 */
void FastTransposeSMatrix(const TSMatrix *M, TSMatrix *T) {
    int num[MAXSIZE], cpot[MAXSIZE];
    int col, p, q;

    T->mu = M->nu; T->nu = M->mu; T->tu = M->tu;
    if (T->tu == 0) { return; }

    for (col = 1; col <= M->nu; col++) { num[col] = 0; }
    for (p = 0; p < M->tu; p++) { num[M->data[p].j]++; }
    cpot[1] = 0;
    for (col = 2; col <= M->nu; col++) { cpot[col] = cpot[col-1] + num[col-1]; }

    for (p = 0; p < M->tu; p++) {
        col = M->data[p].j;
        q = cpot[col];
        T->data[q].i = col;
        T->data[q].j = M->data[p].i;
        T->data[q].e = M->data[p].e;
        cpot[col]++;
    }
}

static void printM(const char *name, const TSMatrix *M) {
    int k;
    printf("%s：%d 行 %d 列，%d 个非零元\n", name, M->mu, M->nu, M->tu);
    for (k = 0; k < M->tu; k++) {
        printf("  (%d,%d) = %d\n", M->data[k].i, M->data[k].j, M->data[k].e);
    }
}

int main(void) {
    TSMatrix M, T;
    int rows[6] = {1, 2, 3, 4, 5, 6};
    int cols[6] = {2, 1, 3, 2, 4, 1};
    int vals[6] = {3, 5, 7, 9, 2, 8};
    int k;

    M.mu = 6; M.nu = 4; M.tu = 6;
    for (k = 0; k < M.tu; k++) {
        M.data[k].i = rows[k];
        M.data[k].j = cols[k];
        M.data[k].e = vals[k];
    }

    printM("原矩阵 M", &M);
    FastTransposeSMatrix(&M, &T);
    printf("\n");
    printM("转置矩阵 T", &T);
    return 0;
}

#include <stdio.h>
#include <string.h>

/* 返回子串 sub 在主串 s 中第一次出现的位置（从 1 计），未找到返回 0 */
int strLocate(const char *s, const char *sub)
{
    const char *p;

    if (sub[0] == '\0') {
        return 1;                /* 约定：空串位于任何串的开头 */
    }
    p = strstr(s, sub);
    if (p == NULL) {
        return 0;
    }
    return (int)(p - s) + 1;     /* ★ 下标差 + 1 转成「位置」 */
}

/* 统计 sub 在 s 中出现的次数（按不重叠计：匹配后跳过整个 sub） */
int countOccur(const char *s, const char *sub)
{
    const char *p = s;
    int count = 0;
    int subLen = (int)strlen(sub);

    if (subLen == 0) {
        return 0;                /* 空串不计，否则会在每个间隙都"匹配"一次 */
    }
    /* ★ p 始终是「还没扫描的部分」的起始地址，全程只用一套坐标系 */
    while ((p = strstr(p, sub)) != NULL) {
        count++;
        p += subLen;             /* 跳过已匹配部分，实现不重叠计数 */
    }
    return count;
}

int main(void)
{
    const char *s = "abcab";
    const char *empty = "";
    const char *blank = "   ";
    int n = (int)strlen(s);

    printf("主串 \"%s\" 长度 = %d\n", s, n);
    printf("空串长度 = %d，空格串(3个空格)长度 = %d\n",
           (int)strlen(empty), (int)strlen(blank));

    printf("\n子串定位（位置从 1 计，未找到为 0）:\n");
    printf("  \"bca\" 在 \"abcab\" 中位置 = %d\n", strLocate(s, "bca"));
    printf("  \"ab\"  在 \"abcab\" 中位置 = %d，出现次数 = %d\n",
           strLocate(s, "ab"), countOccur(s, "ab"));
    printf("  \"cb\"  在 \"abcab\" 中位置 = %d（c 与 b 不相邻，不是子串）\n", strLocate(s, "cb"));
    printf("  \"xyz\" 在 \"abcab\" 中位置 = %d\n", strLocate(s, "xyz"));

    printf("\n子串个数验证（按位置数，含空串）:\n");
    printf("  n=%d 公式 n(n+1)/2+1 = %d\n", n, n * (n + 1) / 2 + 1);
    printf("  \"aaa\" n=3 公式 = %d，但不同内容只有 4 个（空/a/aa/aaa）\n",
           3 * 4 / 2 + 1);

    printf("\nstrcmp 比较: strcmp(\"abc\",\"abd\") = %d（<0 表示前者小）\n",
           strcmp("abc", "abd"));
    return 0;
}

#include <stdio.h>
#include <string.h>

#define MAXLEN 10

/* 定长顺序串：下标 0 存长度，1..MAXLEN 存字符（教材约定） */
typedef struct {
    char ch[MAXLEN + 1];
} SString;

/* 把 C 字符串装入定长串；超长则截断，返回实际装入的字符数 */
int strAssign(SString *s, const char *src)
{
    int i = 0;

    while (src[i] != '\0' && i < MAXLEN) {   /* ★ i < MAXLEN 是截断点 */
        s->ch[i + 1] = src[i];
        i++;
    }
    s->ch[0] = (char)i;                      /* 0 号单元存长度 */
    return i;
}

int strLength(const SString *s)
{
    return (unsigned char)s->ch[0];          /* O(1) 取长度 */
}

/* 打印定长串（不能直接用 printf("%s")，因为没有 \0） */
void strPrint(const char *tag, const SString *s)
{
    int i, len = strLength(s);

    printf("%s", tag);
    for (i = 1; i <= len; i++) {
        printf("%c", s->ch[i]);
    }
    printf("  (长度=%d)\n", len);
}

/* 拼接 t 到 s 之后；放不下则截断，返回是否发生截断 */
int strConcat(SString *s, const SString *t)
{
    int i, slen = strLength(s), tlen = strLength(t);
    int truncated = 0;

    for (i = 1; i <= tlen; i++) {
        if (slen + i > MAXLEN) {             /* 放不下了 */
            truncated = 1;
            break;
        }
        s->ch[slen + i] = t->ch[i];
    }
    if (truncated) {
        s->ch[0] = (char)MAXLEN;
    } else {
        s->ch[0] = (char)(slen + tlen);
    }
    return truncated;
}

/* 安全的 C 字符串复制：显式补结束符 */
void safeCopy(char *dst, const char *src, int cap)
{
    strncpy(dst, src, (size_t)(cap - 1));
    dst[cap - 1] = '\0';                     /* ★ strncpy 不保证补，必须自己补 */
}

int main(void)
{
    SString a, b;
    char buf[6];
    int n;

    printf("MAXLEN = %d\n\n", MAXLEN);

    n = strAssign(&a, "hello");
    strPrint("a = 装入 \"hello\" →", &a);
    printf("  strAssign 返回 %d（实际装入字符数）\n", n);

    n = strAssign(&b, "this string is way too long");
    strPrint("b = 装入超长串 →", &b);
    printf("  ★ 发生截断：源串长 %d，只装入 %d 个字符，且不报错\n",
           (int)strlen("this string is way too long"), n);

    printf("\n拼接演示:\n");
    strAssign(&a, "abc");
    strAssign(&b, "defgh");
    printf("  a=\"abc\" b=\"defgh\"，拼接是否截断 = %d\n", strConcat(&a, &b));
    strPrint("  结果 a =", &a);

    strAssign(&a, "abcdefgh");
    strAssign(&b, "ijkl");
    printf("  a=\"abcdefgh\" b=\"ijkl\"，拼接是否截断 = %d\n", strConcat(&a, &b));
    strPrint("  结果 a =", &a);

    printf("\nsafeCopy 演示（缓冲区只有 6 字节）:\n");
    safeCopy(buf, "hello world", 6);
    printf("  buf = \"%s\" strlen=%d（被截断但有结束符，不会越界读）\n",
           buf, (int)strlen(buf));
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char *ch;                    /* 堆上字符数组，空串时为 NULL */
    int length;
} HString;

void hstrInit(HString *s)
{
    s->ch = NULL;                /* ★ 统一用 NULL 表示空串 */
    s->length = 0;
}

/* 赋值：先释放旧空间，再按源串长度精确申请 */
int hstrAssign(HString *s, const char *src)
{
    int len = (int)strlen(src);

    if (s->ch != NULL) {
        free(s->ch);             /* ★ 不 free 旧的会泄漏 */
        s->ch = NULL;
    }
    if (len == 0) {
        s->length = 0;
        return 0;
    }
    s->ch = (char *)malloc((size_t)len + 1);   /* +1 给结束符 */
    if (s->ch == NULL) {
        s->length = 0;
        return 1;                /* 分配失败 */
    }
    strcpy(s->ch, src);
    s->length = len;
    return 0;
}

/* 拼接：realloc 到 len1+len2，用临时指针接收以防失败丢原指针 */
int hstrConcat(HString *s, const HString *t)
{
    int newLen = s->length + t->length;
    char *tmp;

    if (t->length == 0) {
        return 0;                /* 拼空串，无需扩容 */
    }
    if (newLen == 0) {
        return 0;
    }
    tmp = (char *)realloc(s->ch, (size_t)newLen + 1);
    if (tmp == NULL) {
        return 1;                /* ★ 失败：原块仍有效，s->ch 未被破坏 */
    }
    s->ch = tmp;                 /* 成功后才覆盖原指针 */
    memcpy(s->ch + s->length, t->ch, (size_t)t->length);
    s->ch[newLen] = '\0';
    s->length = newLen;
    return 0;
}

void hstrPrint(const char *tag, const HString *s)
{
    printf("%s", tag);
    if (s->ch == NULL) {
        printf("(空串)");
    } else {
        printf("\"%s\"", s->ch);
    }
    printf("  length=%d\n", s->length);
}

/* 销毁：释放后置 NULL，避免悬空指针 */
void hstrDestroy(HString *s)
{
    free(s->ch);                 /* free(NULL) 是安全的空操作 */
    s->ch = NULL;
    s->length = 0;
}

int main(void)
{
    HString a, b, c;

    hstrInit(&a);
    hstrInit(&b);
    hstrInit(&c);

    hstrPrint("初始 a = ", &a);

    hstrAssign(&a, "data");
    hstrPrint("赋值 a = \"data\" → ", &a);

    hstrAssign(&a, "structures");      /* 再次赋值：旧空间已被 free */
    hstrPrint("再赋值 a = \"structures\" → ", &a);

    hstrAssign(&b, "-and-algorithms");
    hstrConcat(&a, &b);
    hstrPrint("拼接 b 后 a = ", &a);

    hstrAssign(&c, "");
    hstrConcat(&a, &c);
    hstrPrint("拼接空串后 a = ", &a);

    printf("\nstrcmp 比较: %d\n", strcmp(a.ch, "structures-and-algorithms"));
    printf("a.length=%d strlen(a.ch)=%d（两者应一致）\n",
           a.length, (int)strlen(a.ch));

    hstrDestroy(&a);
    hstrDestroy(&b);
    hstrDestroy(&c);
    hstrPrint("销毁后 a = ", &a);
    printf("销毁后二次 destroy 也安全: ");
    hstrDestroy(&a);               /* free(NULL) 无操作 */
    printf("OK\n");
    return 0;
}

#include <stdio.h>
#include <string.h>

/* BF 匹配，*cmp 返回实际发生的字符比较次数 */
int indexBF(const char *s, const char *t, int *cmp)
{
    int n = (int)strlen(s);
    int m = (int)strlen(t);
    int i = 0, j = 0;

    *cmp = 0;
    while (i < n && j < m) {
        (*cmp)++;
        if (s[i] == t[j]) {
            i++;
            j++;
        } else {
            i = i - j + 1;       /* ★ 主串指针回溯到本次起点的下一位 */
            j = 0;
        }
    }
    if (j == m) {
        return i - j;            /* 匹配起点 */
    }
    return -1;
}

static void report(const char *s, const char *t)
{
    int cmp = 0, pos;

    pos = indexBF(s, t, &cmp);
    printf("主串 \"%s\"  模式 \"%s\"\n", s, t);
    printf("  n=%d m=%d 匹配位置=%d 比较次数=%d 上界(n-m+1)*m=%d\n",
           (int)strlen(s), (int)strlen(t), pos, cmp,
           ((int)strlen(s) - (int)strlen(t) + 1) * (int)strlen(t));
}

int main(void)
{
    char worst[24], pattern[12];
    int i;

    printf("== 一般情形 ==\n");
    report("abcabcabd", "abcabd");
    report("hello world", "world");
    report("hello world", "xyz");

    printf("\n== 最好情形（第一次就成功）==\n");
    report("abcdef", "abc");

    printf("\n== 最坏情形构造 ==\n");
    /* 主串 aaaa...ab，模式 aa...ab：每个起点都比到最后一个字符才失配 */
    for (i = 0; i < 20; i++) {
        worst[i] = 'a';
    }
    worst[20] = 'b';
    worst[21] = '\0';
    for (i = 0; i < 9; i++) {
        pattern[i] = 'a';
    }
    pattern[9] = 'b';
    pattern[10] = '\0';
    report(worst, pattern);

    printf("\n== 空模式串 ==\n");
    report("abc", "");
    return 0;
}

#include <stdio.h>
#include <string.h>

#define MAXM 32

/* 求 next 数组：next[j] = t[0..j-1] 的最长相等真前后缀长度，next[0] = -1 */
void getNext(const char *t, int *next)
{
    int j = 0, k = -1;
    int m = (int)strlen(t);

    next[0] = -1;
    while (j < m - 1) {
        if (k == -1 || t[j] == t[k]) {
            j++;
            k++;
            next[j] = k;         /* t[0..j-1] 的最长相等真前后缀长度是 k */
        } else {
            k = next[k];         /* ★ 用已算出的 next 回退，不重新扫描 */
        }
    }
}

/* KMP 匹配，*cmp 只记录真实发生的字符比较次数（j==-1 的推进不计） */
int indexKMP(const char *s, const char *t, const int *next, int *cmp)
{
    int n = (int)strlen(s);
    int m = (int)strlen(t);
    int i = 0, j = 0;

    *cmp = 0;
    while (i < n && j < m) {
        if (j == -1) {
            i++;                 /* 模式串首字符都对不上：主串前进，不算一次比较 */
            j = 0;
            continue;
        }
        (*cmp)++;
        if (s[i] == t[j]) {
            i++;
            j++;
        } else {
            j = next[j];         /* ★ i 不动，只把 j 跳到 next[j] */
        }
    }
    if (j == m) {
        return i - j;
    }
    return -1;
}

static void showNext(const char *t)
{
    int next[MAXM], j, m = (int)strlen(t);

    getNext(t, next);
    printf("模式串 \"%s\" 的 next 数组:\n  j    :", t);
    for (j = 0; j < m; j++) {
        printf("%4d", j);
    }
    printf("\n  t[j] :");
    for (j = 0; j < m; j++) {
        printf("%4c", t[j]);
    }
    printf("\n  next :");
    for (j = 0; j < m; j++) {
        printf("%4d", next[j]);
    }
    printf("\n");
}

static void run(const char *s, const char *t)
{
    int next[MAXM], cmp = 0, pos;

    if ((int)strlen(t) >= MAXM) {
        printf("模式串过长，跳过\n");
        return;
    }
    getNext(t, next);
    pos = indexKMP(s, t, next, &cmp);
    printf("主串 \"%s\" 模式 \"%s\" → 位置=%d KMP比较次数=%d\n", s, t, pos, cmp);
}

int main(void)
{
    char worst[24], pattern[12];
    int i;

    showNext("abcabd");
    printf("\n");
    showNext("aaaaab");

    printf("\n== 匹配实例 ==\n");
    run("abcabcabd", "abcabd");
    run("hello world", "world");
    run("hello world", "xyz");

    printf("\n== 最坏情形对照（BF 在此打满 O(n*m)）==\n");
    for (i = 0; i < 20; i++) {
        worst[i] = 'a';
    }
    worst[20] = 'b';
    worst[21] = '\0';
    for (i = 0; i < 9; i++) {
        pattern[i] = 'a';
    }
    pattern[9] = 'b';
    pattern[10] = '\0';
    run(worst, pattern);
    printf("BF 在同一实例下需要 120 次比较，KMP 只需 n+m 量级\n");
    return 0;
}

#include <stdio.h>
#include <string.h>

#define MAXM 32

/* 求 next 数组，*backtracks 记录 k = next[k] 回退发生的次数 */
void getNext(const char *t, int *next, int *backtracks)
{
    int j = 0, k = -1;
    int m = (int)strlen(t);

    *backtracks = 0;
    next[0] = -1;
    while (j < m - 1) {          /* ★ j < m-1，不是 j < m */
        if (k == -1 || t[j] == t[k]) {
            j++;
            k++;
            next[j] = k;
        } else {
            k = next[k];         /* 回退到次长相等真前后缀 */
            (*backtracks)++;
        }
    }
}

static void show(const char *t)
{
    int next[MAXM], j, m = (int)strlen(t), back = 0;

    if (m >= MAXM) {
        printf("模式串过长，跳过\n");
        return;
    }
    getNext(t, next, &back);
    printf("t = \"%s\"  (m=%d)\n", t, m);
    printf("  j     :");
    for (j = 0; j < m; j++) {
        printf("%4d", j);
    }
    printf("\n  t[j]  :");
    for (j = 0; j < m; j++) {
        printf("%4c", t[j]);
    }
    printf("\n  next  :");
    for (j = 0; j < m; j++) {
        printf("%4d", next[j]);
    }
    printf("\n  回退次数=%d（应远小于 m，验证 O(m)）\n\n", back);
}

int main(void)
{
    show("abaabc");
    show("abcabd");
    show("aaaaab");
    show("ababaa");
    show("a");
    show("ab");
    return 0;
}

#include <stdio.h>
#include <string.h>

#define MAXM 32

void getNext(const char *t, int *next)
{
    int j = 0, k = -1;
    int m = (int)strlen(t);

    next[0] = -1;
    while (j < m - 1) {
        if (k == -1 || t[j] == t[k]) {
            j++;
            k++;
            next[j] = k;
        } else {
            k = next[k];
        }
    }
}

/* 由 next 推 nextval：t[j] == t[next[j]] 时继承 nextval[next[j]] */
void getNextval(const char *t, const int *next, int *nextval)
{
    int j, m = (int)strlen(t);

    nextval[0] = -1;
    for (j = 1; j < m; j++) {
        if (next[j] >= 0 && t[j] == t[next[j]]) {
            nextval[j] = nextval[next[j]];   /* ★ 继承已改进的值，链式跳过 */
        } else {
            nextval[j] = next[j];
        }
    }
}

/* 通用 KMP，传入 next 或 nextval 都可以；*cmp 只统计真实字符比较 */
int kmpMatch(const char *s, const char *t, const int *nxt, int *cmp)
{
    int n = (int)strlen(s), m = (int)strlen(t);
    int i = 0, j = 0;

    *cmp = 0;
    while (i < n && j < m) {
        if (j == -1) {
            i++;                 /* 首字符就对不上：主串前进，不算一次比较 */
            j = 0;
            continue;
        }
        (*cmp)++;
        if (s[i] == t[j]) {
            i++;
            j++;
        } else {
            j = nxt[j];
        }
    }
    return (j == m) ? i - j : -1;
}

static void compare(const char *s, const char *t)
{
    int next[MAXM], nextval[MAXM], j, m = (int)strlen(t);
    int cmp1 = 0, cmp2 = 0, p1, p2;

    if (m >= MAXM) {
        printf("模式串过长\n");
        return;
    }
    getNext(t, next);
    getNextval(t, next, nextval);

    printf("模式串 \"%s\"\n", t);
    printf("  j      :");
    for (j = 0; j < m; j++) {
        printf("%4d", j);
    }
    printf("\n  next   :");
    for (j = 0; j < m; j++) {
        printf("%4d", next[j]);
    }
    printf("\n  nextval:");
    for (j = 0; j < m; j++) {
        printf("%4d", nextval[j]);
    }
    p1 = kmpMatch(s, t, next, &cmp1);
    p2 = kmpMatch(s, t, nextval, &cmp2);
    printf("\n  主串 \"%s\"：next 用 %d 次比较(位置%d)，nextval 用 %d 次(位置%d)，省 %d 次\n\n",
           s, cmp1, p1, cmp2, p2, cmp1 - cmp2);
}

int main(void)
{
    char worst[24], pat[12];
    int i;

    printf("== 收益实例：主串在模式串中部失配 ==\n");
    compare("aaac", "aaab");

    printf("== nextval 数组形态：模式串字符几乎全相同 ==\n");
    for (i = 0; i < 20; i++) {
        worst[i] = 'a';
    }
    worst[20] = 'b';
    worst[21] = '\0';
    for (i = 0; i < 9; i++) {
        pat[i] = 'a';
    }
    pat[9] = 'b';
    pat[10] = '\0';
    compare(worst, pat);

    printf("== 部分重复：nextval 有改动但本例未被触发 ==\n");
    compare("abcabcabd", "abcabd");

    printf("== 字符互不相同：nextval 与 next 完全一样 ==\n");
    compare("abcdefg", "xyz");
    return 0;
}

#include <stdio.h>
#include <string.h>

#define MAXLEN 32

/* ① 赋值：容量不足返回 1（明确报错，不静默截断） */
int strAssign(char *s, const char *t)
{
    int i = 0;

    while (t[i] != '\0') {
        if (i >= MAXLEN - 1) {
            s[i] = '\0';
            return 1;            /* 容量不足 */
        }
        s[i] = t[i];
        i++;
    }
    s[i] = '\0';
    return 0;
}

/* ② 比较：返回正/0/负，字符必须转 unsigned char */
int strCompare(const char *s, const char *t)
{
    while (*s != '\0' && *t != '\0' && *s == *t) {
        s++;
        t++;
    }
    return (int)(unsigned char)*s - (int)(unsigned char)*t;
}

/* ③ 求长：扫到 \0，O(n) */
int strLength(const char *s)
{
    int n = 0;

    while (s[n] != '\0') {
        n++;
    }
    return n;
}

/* ④ 拼接：从 s 的结束符处开始写，写完补新的 \0；容量不足返回 1 */
int strConcat(char *s, const char *t)
{
    int i = 0, j = 0;

    while (s[i] != '\0') {
        i++;                     /* 找到 s 的末尾 */
    }
    while (t[j] != '\0') {
        if (i >= MAXLEN - 1) {
            s[i] = '\0';
            return 1;
        }
        s[i++] = t[j++];
    }
    s[i] = '\0';                 /* ★ 必须补结束符 */
    return 0;
}

/* ⑤ 求子串：pos 从 1 计；越界返回 1，不静默截断 */
int subString(char *sub, const char *s, int pos, int len)
{
    int n = strLength(s), i;

    if (pos < 1 || len < 0 || pos + len - 1 > n) {
        sub[0] = '\0';
        return 1;                /* ★ 越界明确报错 */
    }
    for (i = 0; i < len; i++) {
        sub[i] = s[pos - 1 + i]; /* pos 从 1 计，下标是 pos-1 */
    }
    sub[len] = '\0';
    return 0;
}

/* ⑥ 定位：返回第一次出现的位置（从 1 计），未找到返回 0 */
int strIndex(const char *s, const char *t)
{
    int n = strLength(s), m = strLength(t), i, j, k;

    if (m == 0) {
        return 1;                /* 约定空串位于开头 */
    }
    for (i = 0; i <= n - m; i++) {
        for (j = 0, k = i; j < m && s[k] == t[j]; j++, k++) {
            ;                    /* 逐字符比对 */
        }
        if (j == m) {
            return i + 1;        /* 位置从 1 计 */
        }
    }
    return 0;
}

int main(void)
{
    char a[MAXLEN], b[MAXLEN], sub[16];
    int rc, len;

    strAssign(a, "data structure");
    strAssign(b, "course");
    printf("a = \"%s\"  长度 = %d\n", a, strLength(a));
    printf("b = \"%s\"  长度 = %d\n", b, strLength(b));

    printf("\n比较: strCompare(a,b) = %d（>0 表示 a 大）\n", strCompare(a, b));
    printf("      strCompare(a,a) = %d\n", strCompare(a, a));
    printf("      strCompare(\"abc\",\"abd\") = %d（<0）\n", strCompare("abc", "abd"));

    printf("\n子串（pos 从 1 计）:\n");
    printf("  SubString(a,6,9) = \"%s\" 返回码 %d\n",
           subString(sub, a, 6, 9) == 0 ? sub : "(失败)", 0);
    printf("  SubString(a,1,4)  = \"%s\"\n", subString(sub, a, 1, 4) == 0 ? sub : "(失败)");
    printf("  SubString(a,10,99) 返回码 = %d（越界报错，不截断）\n",
           subString(sub, a, 10, 99));

    printf("\n定位:\n");
    printf("  Index(a,\"structure\") = %d\n", strIndex(a, "structure"));
    printf("  Index(a,\"data\")      = %d\n", strIndex(a, "data"));
    printf("  Index(a,\"xyz\")       = %d\n", strIndex(a, "xyz"));

    printf("\n拼接:\n");
    /* ★ 先调用再打印：printf 的实参求值顺序 C 标准不规定，
       若把 strConcat(a,b) 与 strLength(a) 写在同一次调用里，
       strLength 可能先于 strConcat 执行，读到的是拼接前的旧长度 */
    rc = strConcat(a, "-");
    len = strLength(a);
    printf("  strConcat(a,\"-\") 返回码 = %d → a = \"%s\"  长度 = %d\n", rc, a, len);

    rc = strConcat(a, b);
    len = strLength(a);
    printf("  strConcat(a,b)    返回码 = %d → a = \"%s\"  长度 = %d\n", rc, a, len);
    return 0;
}

#include <stdio.h>

#define M 3
#define N 4

int main(void)
{
    char a[M][N];
    char *base;
    int i, j, actual, rowMajor, colMajor;
    int rowHit = 0, colHit = 0;

    /* 填入 A..L，便于观察内存里的实际排列次序 */
    for (i = 0; i < M; i++) {
        for (j = 0; j < N; j++) {
            a[i][j] = (char)('A' + i * N + j);
        }
    }
    base = &a[0][0];

    printf("a[%d][%d] 共 %d 个 char 元素（每个 1 字节，偏移量正好等于公式值）\n",
           M, N, M * N);
    printf("内存中依次是：");
    for (i = 0; i < M * N; i++) {
        printf("%c", base[i]);
    }
    printf("\n\n");

    printf("行主序 LOC(i,j) = base + (i*N + j)；列主序 LOC(i,j) = base + (j*M + i)\n");
    for (i = 0; i < M; i++) {
        for (j = 0; j < N; j++) {
            actual = (int)(&a[i][j] - base);   /* char* 相减，单位就是字节 */
            rowMajor = i * N + j;
            colMajor = j * M + i;
            if (actual == rowMajor) {
                rowHit++;
            }
            if (actual == colMajor) {
                colHit++;
            }
            printf("a[%d][%d] 内容=%c 实际偏移=%d 行主序=%d(%s) 列主序=%d(%s)\n",
                   i, j, a[i][j], actual,
                   rowMajor, actual == rowMajor ? "命中" : "不符",
                   colMajor, actual == colMajor ? "命中" : "不符");
        }
    }

    printf("\n行主序命中 %d/%d，列主序命中 %d/%d → C 语言按行主序存储\n",
           rowHit, M * N, colHit, M * N);
    printf("sizeof(a)=%d sizeof(a[0])=%d sizeof(a[0][0])=%d\n",
           (int)sizeof(a), (int)sizeof(a[0]), (int)sizeof(a[0][0]));
    return 0;
}

#include <stdio.h>

#define M 3
#define N 4

/* 形参写 int a[] 与 int *a 完全等价——编译器会把数组形参「调整」成指针，
   这正是 sizeof 得到指针大小的原因。这里直接写成 int *a，
   一是语义更诚实，二是避免 gcc 的 -Wsizeof-array-argument 警告。 */
void sizeInFunc(int *a, int n)
{
    printf("函数内 sizeof(a)=%d（指针大小），必须靠形参 n=%d 才知道元素个数\n",
           (int)sizeof(a), n);
}

/* 二维数组形参：除第一维外都必须给出，编译器要用 N 算地址 */
int sumMatrix(int a[][N], int rows)
{
    int i, j, s = 0;

    for (i = 0; i < rows; i++) {
        for (j = 0; j < N; j++) {
            s += a[i][j];
        }
    }
    return s;
}

/* 数组指针：指向「一整行」的指针，p++ 一次跨过 N 个 int */
int sumByRowPointer(int (*p)[N], int rows)
{
    int i, j, s = 0;

    for (i = 0; i < rows; i++) {
        for (j = 0; j < N; j++) {
            s += (*p)[j];          /* 等价于 p[i][j] */
        }
        p++;                       /* ★ 一次跨过一整行 */
    }
    return s;
}

int main(void)
{
    int a[6] = {1, 2, 3, 4, 5, 6};
    int m[M][N];
    int *ptrArray[3];              /* 指针数组：3 个 int* */
    int (*arrayPtr)[N];            /* 数组指针：1 个指向 int[N] 的指针 */
    int i, j;

    for (i = 0; i < M; i++) {
        for (j = 0; j < N; j++) {
            m[i][j] = i * N + j + 1;   /* 填入 1..12 */
        }
    }
    ptrArray[0] = a;
    ptrArray[1] = a + 2;
    ptrArray[2] = a + 5;
    arrayPtr = m;

    printf("== sizeof 的三个例外 ==\n");
    printf("sizeof(a)=%d = 6*%d（数组名在 sizeof 里不退化）\n",
           (int)sizeof(a), (int)sizeof(int));
    printf("sizeof(&a)=%d（取地址里也不退化，类型是 int(*)[6]）\n",
           (int)sizeof(&a));
    printf("sizeof(a+0)=%d（普通表达式里退化成 int*）\n", (int)sizeof(a + 0));
    sizeInFunc(a, 6);

    printf("\n== 指针数组 vs 数组指针 ==\n");
    printf("ptrArray 是 3 个指针，sizeof=%d；指向 a 的第 0/2/5 个元素："
           "*ptrArray[0]=%d *ptrArray[1]=%d *ptrArray[2]=%d\n",
           (int)sizeof(ptrArray), *ptrArray[0], *ptrArray[1], *ptrArray[2]);
    printf("arrayPtr 是 1 个指针，sizeof=%d；指向 m 的第 0 行："
           "(*arrayPtr)[0]=%d (*arrayPtr)[3]=%d\n",
           (int)sizeof(arrayPtr), (*arrayPtr)[0], (*arrayPtr)[3]);
    printf("arrayPtr+1 跨过一整行：(*(arrayPtr+1))[0]=%d（应为 5）\n",
           (*(arrayPtr + 1))[0]);

    printf("\n== 二维数组与形参 ==\n");
    printf("sizeof(m)=%d = %d*%d*%d\n", (int)sizeof(m), M, N, (int)sizeof(int));
    printf("sizeof(m[0])=%d（一行的字节数）\n", (int)sizeof(m[0]));
    printf("sumMatrix=%d sumByRowPointer=%d（1..12 之和应为 78）\n",
           sumMatrix(m, M), sumByRowPointer(m, M));
    return 0;
}

