/* 长度 = 最外层兄弟结点的个数 */
static int length(GList ls)
{
    int n = 0;
    GList p;

    for (p = ls; p != NULL; p = p->tp) {
        n++;
    }
    return n;
}

/* 深度：空表 1；否则 1 + 各元素深度的最大值（原子算 0） */
static int depth(GList ls)
{
    int maxD = 0, d;
    GList p;

    if (ls == NULL) {
        return 1;
    }
    for (p = ls; p != NULL; p = p->tp) {
        d = (p->tag == ATOM) ? 0 : depth(p->val.hp);
        if (d > maxD) {
            maxD = d;
        }
    }
    return maxD + 1;
}

static void destroyGL(GList ls)
{
    GList p, next;

    for (p = ls; p != NULL; p = next) {
        next = p->tp;
        if (p->tag == LIST) {
            destroyGL(p->val.hp);
        }
        free(p);
    }
}

static void describe(const char *name, GList ls)
{
    printf("%s 长度=%d 深度=%d", name, length(ls), depth(ls));
    if (ls == NULL) {
        printf(" 表头=无（空表无表头表尾） 表尾=无\n");
        return;
    }
    if (ls->tag == ATOM) {
        printf(" 表头=原子 %c", ls->val.atom);
    } else {
        printf(" 表头=子表(长度%d 深度%d)", length(ls->val.hp), depth(ls->val.hp));
    }
    printf(" 表尾长度=%d\n", length(ls->tp));
}

