static int depthTrace(GList ls, int level, int *calls)
{
    int maxD = 0, d;
    GList p;

    (*calls)++;
    if (ls == NULL) {
        pad(level);
        printf("depth(空表) -> 1        [递归基]\n");
        return 1;
