            printf("元素 ATOM '%c' -> 深度 0   [递归基，不再下探]\n", p->val.atom);
            d = 0;
        } else {
            pad(level + 1);
            printf("元素 LIST -> 下探它的孩子链：\n");
            d = depthTrace(p->val.hp, level + 2, calls);
            pad(level + 1);
            printf("该子表返回深度 = %d\n", d);
