## 深复制 copyGL

```c
GList copyGL(GList ls)
{
    GList p, newHead = NULL, *tailSlot = &newHead;

    for (p = ls; p != NULL; p = p->tp) {
        GList node = (GList)malloc(sizeof(GLNode));
        node->tag = p->tag;
        if (p->tag == ATOM) node->val.atom = p->val.atom;
        else                node->val.hp   = copyGL(p->val.hp);   /* ★ 递归复制子表 */
        node->tp = NULL;
        *tailSlot = node;          /* 挂到结果链的末尾 */
        tailSlot = &node->tp;
    }
    return newHead;
}
```

用「指向尾指针的指针」`tailSlot` 是构造链表的标准技巧：
新结点总是挂到 `*tailSlot`，然后把 tailSlot 移到新结点的 tp 域上，
这样**不需要特殊处理第一个结点**，也不需要每次从头扫到尾（否则是 O(n²)）。

## 浅复制的陷阱

```c
GList E2 = E;        /* ★ 浅复制：两个变量指向同一串结点 */
```

浅复制之后：

- 修改 `E2` 里的原子，`E` 也跟着变（同一块内存）
- `destroyGL(E2)` 之后 `E` 变成悬空指针，再用就是 use-after-free
- `destroyGL(E); destroyGL(E2);` 是 **double free**，通常直接崩溃

**只有深复制才能让两个表真正独立。**

## 原子替换：递归下降

```c
int replaceAtom(GList ls, char from, char to)
{
    GList p;
    int n = 0;

    for (p = ls; p != NULL; p = p->tp) {      /* 横向：扫过兄弟 */
        if (p->tag == ATOM) {
            if (p->val.atom == from) { p->val.atom = to; n++; }
        } else {
            n += replaceAtom(p->val.hp, from, to);   /* 纵向：深入子表 */
        }
    }
    return n;                                  /* 返回替换次数，便于验证 */
}
```

「**横向走 tp、纵向走 hp**」是所有广义表递归算法的统一骨架，
depth / printGL / countAtoms / replaceAtom 全都长这样，只是每个结点做的事不同。
返回替换次数是个好习惯——它让调用方能验证操作确实生效了，而不是静默什么都没做。

## 共享子表与引用计数

广义表允许两个表共享同一个子表（`A = (x, y)`、`B = (z, A)`、`C = (w, A)`，
B 和 C 共享 A）。此时：

| 方案 | 做法 | 问题 |
|---|---|---|
| 直接 free | destroy 时无脑释放 | 第二个持有者拿到悬空指针 |
| **引用计数** | 每个结点加 `refcount`，共享时 ++，释放时 --，减到 0 才真 free | 无法处理环（递归表） |
| 标记-清除 | 从根出发标记可达结点，其余回收 | 实现复杂，教材一般不涉及 |

教材的 destroy 通常**假设无共享**，所以直接递归 free 就够了；
但一旦题目里出现「两个表共享子表」，就必须上引用计数，否则一定出错。

examples.code:
#include <stdio.h>
#include <stdlib.h>

typedef enum { ATOM, LIST } ElemTag;

typedef struct GLNode {
    ElemTag tag;
    union {
        char atom;
        struct GLNode *hp;
    } val;
    struct GLNode *tp;
} GLNode, *GList;

static GList mkAtom(char c, GList tp)
{
    GList p = (GList)malloc(sizeof(GLNode));

    if (p == NULL) {
        return NULL;
    }
    p->tag = ATOM;
    p->val.atom = c;
    p->tp = tp;
    return p;
}

static GList mkList(GList hp, GList tp)
{
    GList p = (GList)malloc(sizeof(GLNode));

    if (p == NULL) {
        return NULL;
    }
    p->tag = LIST;
    p->val.hp = hp;
    p->tp = tp;
    return p;
}

/* 深复制：为每个结点新建内存，子表递归复制 */
static GList copyGL(GList ls)
{
    GList p, node, newHead = NULL, *tailSlot = &newHead;

    for (p = ls; p != NULL; p = p->tp) {
        node = (GList)malloc(sizeof(GLNode));
        if (node == NULL) {
            return newHead;
        }
        node->tag = p->tag;
        if (p->tag == ATOM) {
            node->val.atom = p->val.atom;
        } else {
            node->val.hp = copyGL(p->val.hp);   /* ★ 递归复制子表 */
        }
        node->tp = NULL;
        *tailSlot = node;                       /* 挂到结果链末尾 */
        tailSlot = &node->tp;                   /* 尾指针前移，避免 O(n^2) 尾插 */
    }
    return newHead;
}

/* 原子替换：横向走 tp、纵向走 hp，返回替换次数 */
static int replaceAtom(GList ls, char from, char to)
{
    GList p;
    int n = 0;

    for (p = ls; p != NULL; p = p->tp) {
        if (p->tag == ATOM) {
            if (p->val.atom == from) {
                p->val.atom = to;
                n++;
            }
        } else {
            n += replaceAtom(p->val.hp, from, to);
        }
    }
    return n;
}

/* 把所有原子统一替换成 to，返回替换次数（用于验证遍历覆盖了全部原子） */
static int replaceAll(GList ls, char to)
{
    GList p;
    int n = 0;

    for (p = ls; p != NULL; p = p->tp) {
        if (p->tag == ATOM) {
            p->val.atom = to;
            n++;
        } else {
            n += replaceAll(p->val.hp, to);
        }
    }
    return n;
}

static void printGL(GList ls)
{
    GList p;
    int first = 1;

    printf("(");
    for (p = ls; p != NULL; p = p->tp) {
        if (!first) {
            printf(",");
        }
        first = 0;
        if (p->tag == ATOM) {
            printf("%c", p->val.atom);
        } else {
            printGL(p->val.hp);
        }
    }
    printf(")");
}

static int countNodes(GList ls)
{
    GList p;
    int n = 0;

    for (p = ls; p != NULL; p = p->tp) {
        n++;
        if (p->tag == LIST) {
            n += countNodes(p->val.hp);
        }
    }
    return n;
}

static int depth(GList ls)
{
    int maxD = 0, d;
    GList p;

    if (ls == NULL) {
        return 1;
    }
    for (p = ls; p != NULL; p = p->tp) {
        d = (p->tag == ATOM) ? 0 : depth(p->val.hp);
        if (d > maxD) {
            maxD = d;
        }
    }
    return maxD + 1;
}

static void destroyGL(GList ls)
{
    GList p, next;

    for (p = ls; p != NULL; p = next) {
        next = p->tp;
        if (p->tag == LIST) {
            destroyGL(p->val.hp);
        }
        free(p);
    }
}

int main(void)
{
    GList E = mkList(mkAtom('a', NULL),
                     mkList(mkAtom('b', mkList(mkAtom('c', mkAtom('d', NULL)), NULL)),
                            NULL));
    GList E2;
    int n;

    printf("原表 E = ");
    printGL(E);
    printf("  结点数 %d 深度 %d\n", countNodes(E), depth(E));

    E2 = copyGL(E);
    printf("复制表 E2 = ");
    printGL(E2);
    printf("  结点数 %d 深度 %d\n", countNodes(E2), depth(E2));
    printf("E 与 E2 指向同一结点吗 = %d（0 表示不同，是深复制）\n", E == E2);

    printf("\n== 第一轮：把 E2 中所有 'b' 换成 'Z' ==\n");
    n = replaceAtom(E2, 'b', 'Z');
    printf("替换次数 = %d\n", n);
    printf("E2 = ");
    printGL(E2);
    printf("\nE  = ");
    printGL(E);
    printf("   <- 原表未受影响，证明是深复制\n");

    printf("\n== 第二轮：把 E2 的所有原子统一换成 '*' ==\n");
    n = replaceAll(E2, '*');
    printf("替换次数 = %d（应等于原子总数）\n", n);
    printf("E2 = ");
    printGL(E2);
    printf("\n");

    destroyGL(E2);
    printf("\nE2 已释放，E 仍然可用：E = ");
    printGL(E);
    printf("\n");
    destroyGL(E);
    printf("E 已释放\n");
    return 0;
}
